insert into public.ecosystem_regions (slug,title_de,title_en,biome,center_lat,center_lon,summary_de,status,source_citations,explorer_data) values ('joshua-tree-extrem','Joshua Tree · Wüste','Joshua Tree · Desert','desert',33.9,-115.9,'Beispielhafte Lernregion: Warum lebt die Wüste nachts auf?','published','[{"label": "NPS · Joshua Tree", "url": "https://www.nps.gov/jotr/learn/nature/animal-adaptations.htm"}]'::jsonb,'{"location_scope": "representative_region", "reviewed_on": "2026-11-28", "discovery_question_de": "Warum lebt die Wüste nachts auf?", "discovery_question_en": "Why does the desert come alive at night?", "discovery_level": "fauna", "zoom_story": [{"id": "region", "min_zoom": 2, "label_de": "Region", "label_en": "Region", "question_de": "Ist die Wüste wirklich leer?", "question_en": "Is the desert really empty?", "answer_de": "In Joshua Tree leben Vögel, Reptilien und Säugetiere. Viele bleiben tagsüber verborgen.", "answer_en": "Joshua Tree supports birds, reptiles and mammals. Many stay hidden during the day.", "source_citations": [{"label": "NPS · Joshua Tree", "url": "https://www.nps.gov/jotr/learn/nature/animal-adaptations.htm"}]}, {"id": "climate", "min_zoom": 3.8, "label_de": "Klima", "label_en": "Climate", "question_de": "Wie entkommen Tiere der Hitze?", "question_en": "How do animals escape the heat?", "answer_de": "Wasserknappheit und extreme Temperaturen prägen den Alltag. Manche Tiere verlagern ihre Aktivität in die Nacht.", "answer_en": "Scarce water and extreme temperatures shape daily life. Some animals shift their activity into the night.", "source_citations": [{"label": "NPS · Joshua Tree", "url": "https://www.nps.gov/jotr/learn/nature/animal-adaptations.htm"}]}, {"id": "fauna", "min_zoom": 7, "label_de": "Tiere", "label_en": "Animals", "question_de": "Warum lebt die Wüste nachts auf?", "question_en": "Why does the desert come alive at night?", "answer_de": "Kängururatten sind nachts aktiv. Erdbauten bieten kleinen Säugetieren und Reptilien Schutz vor der Sommersonne.", "answer_en": "Kangaroo rats are active at night. Burrows shelter small mammals and reptiles from summer sunshine.", "source_citations": [{"label": "NPS · Joshua Tree", "url": "https://www.nps.gov/jotr/learn/nature/animal-adaptations.htm"}], "station_slug": "joshua-tree-extrem-fauna"}, {"id": "soil", "min_zoom": 12, "label_de": "Boden", "label_en": "Soil", "question_de": "Was hält losen Wüstenboden zusammen?", "question_en": "What holds loose desert soil together?", "answer_de": "Cyanobakterien bilden klebrige Fäden. Zusammen mit weiteren Organismen stabilisieren sie Bodenkrusten gegen Erosion. Tritte können diese empfindliche Oberfläche zerstören.", "answer_en": "Cyanobacteria form sticky filaments. Alongside other organisms, they stabilise soil crusts against erosion. Footsteps can destroy this delicate surface.", "source_citations": [{"label": "NPS · Biologische Bodenkrusten", "url": "https://www.nps.gov/jotr/learn/nature/cryptocrusts.htm"}], "station_slug": "joshua-tree-extrem-soil"}], "summary_en": "Representative learning region: Why does the desert come alive at night?"}'::jsonb) on conflict (slug) do nothing;
insert into public.ecosystem_hotspots (slug,region_slug,priority,category,title_de,teaser_de,detail_de,latitude,longitude,status,source_citations,related_paths,explorer_data) values ('joshua-tree-extrem-fauna','joshua-tree-extrem',1,'species','Warum lebt die Wüste nachts auf?','Kängururatten sind nachts aktiv. Erdbauten bieten kleinen Säugetieren und Reptilien Schutz vor der Sommersonne.','Beispielhafte Lernregion. Der räumliche Geltungsbereich ist in der Quelle beschrieben.',33.9,-115.9,'published','[{"label": "NPS · Joshua Tree", "url": "https://www.nps.gov/jotr/learn/nature/animal-adaptations.htm"}]'::jsonb,'[]'::jsonb,'{"title_en": "Why does the desert come alive at night?", "teaser_en": "Kangaroo rats are active at night. Burrows shelter small mammals and reptiles from summer sunshine.", "detail_en": "Representative learning region; see source for geographic scope.", "location_scope": "representative_region", "reviewed_on": "2026-11-28"}'::jsonb) on conflict (slug) do nothing;
insert into public.ecosystem_hotspots (slug,region_slug,priority,category,title_de,teaser_de,detail_de,latitude,longitude,status,source_citations,related_paths,explorer_data) values ('joshua-tree-extrem-soil','joshua-tree-extrem',2,'soil','Was hält losen Wüstenboden zusammen?','Cyanobakterien bilden klebrige Fäden. Zusammen mit weiteren Organismen stabilisieren sie Bodenkrusten gegen Erosion. Tritte können diese empfindliche Oberfläche zerstören.','Beispielhafte Lernregion. Der räumliche Geltungsbereich ist in der Quelle beschrieben.',33.9,-115.9,'published','[{"label": "NPS · Biologische Bodenkrusten", "url": "https://www.nps.gov/jotr/learn/nature/cryptocrusts.htm"}]'::jsonb,'[]'::jsonb,'{"title_en": "What holds loose desert soil together?", "teaser_en": "Cyanobacteria form sticky filaments. Alongside other organisms, they stabilise soil crusts against erosion. Footsteps can destroy this delicate surface.", "detail_en": "Representative learning region; see source for geographic scope.", "location_scope": "representative_region", "reviewed_on": "2026-11-28"}'::jsonb) on conflict (slug) do nothing;
insert into public.ecosystem_regions (slug,title_de,title_en,biome,center_lat,center_lon,summary_de,status,source_citations,explorer_data) values ('rocky-tundra-extrem','Rocky Mountains · Tundra','Rocky Mountains · Tundra','alpine tundra',40.45,-105.75,'Beispielhafte Lernregion: Wer sammelt Heu für den Winter?','published','[{"label": "NPS · Alpine Tundra", "url": "https://www.nps.gov/romo/learn/nature/alpine_tundra_ecosystem.htm"}]'::jsonb,'{"location_scope": "representative_region", "reviewed_on": "2026-11-28", "discovery_question_de": "Wer sammelt Heu für den Winter?", "discovery_question_en": "Who gathers hay for winter?", "discovery_level": "fauna", "zoom_story": [{"id": "region", "min_zoom": 2, "label_de": "Region", "label_en": "Region", "question_de": "Warum fehlen hier die Bäume?", "question_en": "Why are there no trees here?", "answer_de": "Oberhalb der Baumgrenze begrenzen Kälte und häufige starke Winde das Pflanzenwachstum.", "answer_en": "Above the treeline, cold and frequent strong winds restrict plant growth.", "source_citations": [{"label": "NPS · Alpine Tundra", "url": "https://www.nps.gov/romo/learn/nature/alpine_tundra_ecosystem.htm"}]}, {"id": "climate", "min_zoom": 3.8, "label_de": "Klima", "label_en": "Climate", "question_de": "Was verändert der kurze Sommer?", "question_en": "What does a short summer change?", "answer_de": "Pflanzen und Tiere müssen die kurze warme Zeit nutzen. Der Winter bestimmt ihre Überlebensstrategien.", "answer_en": "Plants and animals must use the brief warm season. Winter shapes their survival strategies.", "source_citations": [{"label": "NPS · Alpine Tundra", "url": "https://www.nps.gov/romo/learn/nature/alpine_tundra_ecosystem.htm"}]}, {"id": "fauna", "min_zoom": 7, "label_de": "Tiere", "label_en": "Animals", "question_de": "Wer sammelt Heu für den Winter?", "question_en": "Who gathers hay for winter?", "answer_de": "Amerikanische Pfeifhasen lagern Pflanzenvorräte und bleiben unter isolierendem Schnee aktiv. Gelbbauchmurmeltiere halten dagegen Winterschlaf.", "answer_en": "American pikas store vegetation and remain active beneath insulating snow. Yellow-bellied marmots hibernate instead.", "source_citations": [{"label": "NPS · Alpine Tundra", "url": "https://www.nps.gov/romo/learn/nature/alpine_tundra_ecosystem.htm"}], "station_slug": "rocky-tundra-extrem-fauna"}, {"id": "soil", "min_zoom": 12, "label_de": "Boden", "label_en": "Soil", "question_de": "Warum ist diese Vegetation so empfindlich?", "question_en": "Why is this vegetation so fragile?", "answer_de": "Wiederholte Tritte zerstören Tundrapflanzen. Ungeschützter Boden kann verwehen; die Erholung dauert mitunter Jahrhunderte.", "answer_en": "Repeated footsteps destroy tundra plants. Exposed soil can blow away; recovery may take centuries.", "source_citations": [{"label": "NPS · Alpine Tundra", "url": "https://www.nps.gov/romo/learn/nature/alpine_tundra_ecosystem.htm"}], "station_slug": "rocky-tundra-extrem-soil"}], "summary_en": "Representative learning region: Who gathers hay for winter?"}'::jsonb) on conflict (slug) do nothing;
insert into public.ecosystem_hotspots (slug,region_slug,priority,category,title_de,teaser_de,detail_de,latitude,longitude,status,source_citations,related_paths,explorer_data) values ('rocky-tundra-extrem-fauna','rocky-tundra-extrem',1,'species','Wer sammelt Heu für den Winter?','Amerikanische Pfeifhasen lagern Pflanzenvorräte und bleiben unter isolierendem Schnee aktiv. Gelbbauchmurmeltiere halten dagegen Winterschlaf.','Beispielhafte Lernregion. Der räumliche Geltungsbereich ist in der Quelle beschrieben.',40.45,-105.75,'published','[{"label": "NPS · Alpine Tundra", "url": "https://www.nps.gov/romo/learn/nature/alpine_tundra_ecosystem.htm"}]'::jsonb,'[]'::jsonb,'{"title_en": "Who gathers hay for winter?", "teaser_en": "American pikas store vegetation and remain active beneath insulating snow. Yellow-bellied marmots hibernate instead.", "detail_en": "Representative learning region; see source for geographic scope.", "location_scope": "representative_region", "reviewed_on": "2026-11-28"}'::jsonb) on conflict (slug) do nothing;
insert into public.ecosystem_hotspots (slug,region_slug,priority,category,title_de,teaser_de,detail_de,latitude,longitude,status,source_citations,related_paths,explorer_data) values ('rocky-tundra-extrem-soil','rocky-tundra-extrem',2,'soil','Warum ist diese Vegetation so empfindlich?','Wiederholte Tritte zerstören Tundrapflanzen. Ungeschützter Boden kann verwehen; die Erholung dauert mitunter Jahrhunderte.','Beispielhafte Lernregion. Der räumliche Geltungsbereich ist in der Quelle beschrieben.',40.45,-105.75,'published','[{"label": "NPS · Alpine Tundra", "url": "https://www.nps.gov/romo/learn/nature/alpine_tundra_ecosystem.htm"}]'::jsonb,'[]'::jsonb,'{"title_en": "Why is this vegetation so fragile?", "teaser_en": "Repeated footsteps destroy tundra plants. Exposed soil can blow away; recovery may take centuries.", "detail_en": "Representative learning region; see source for geographic scope.", "location_scope": "representative_region", "reviewed_on": "2026-11-28"}'::jsonb) on conflict (slug) do nothing;
insert into public.ecosystem_regions (slug,title_de,title_en,biome,center_lat,center_lon,summary_de,status,source_citations,explorer_data) values ('antarctic-life-extrem','Antarktis · Kleines Leben','Antarctica · Small life','polar terrestrial habitats',-64.5,-62,'Beispielhafte Lernregion: Welche winzigen Tiere leben hier?','published','[{"label": "Australian Antarctic Program · Land invertebrates", "url": "https://www.antarctica.gov.au/about-antarctica/animals/land-invertebrates/"}]'::jsonb,'{"location_scope": "representative_region", "reviewed_on": "2026-11-28", "discovery_question_de": "Welche winzigen Tiere leben hier?", "discovery_question_en": "Which tiny animals live here?", "discovery_level": "fauna", "zoom_story": [{"id": "region", "min_zoom": 2, "label_de": "Region", "label_en": "Region", "question_de": "Gibt es hier Leben an Land?", "question_en": "Is there life on land here?", "answer_de": "Wirbellose bilden die artenreichste Tiergruppe der Antarktis und subantarktischer Inseln. Dieser Punkt erschließt das überregionale Thema.", "answer_en": "Invertebrates are the most species-rich animal group in Antarctica and sub-Antarctic islands. This point opens the wider regional topic.", "source_citations": [{"label": "Australian Antarctic Program · Land invertebrates", "url": "https://www.antarctica.gov.au/about-antarctica/animals/land-invertebrates/"}]}, {"id": "climate", "min_zoom": 3.8, "label_de": "Wasser", "label_en": "Water", "question_de": "Warum zählt Wasser trotz Eis?", "question_en": "Why does water matter despite the ice?", "answer_de": "Auf dem antarktischen Kontinent beeinflusst Wasser entscheidend, wo wirbellose Tiere vorkommen und wie häufig sie sind.", "answer_en": "On the Antarctic continent, water strongly influences where invertebrates occur and how abundant they are.", "source_citations": [{"label": "Australian Antarctic Program · Land invertebrates", "url": "https://www.antarctica.gov.au/about-antarctica/animals/land-invertebrates/"}]}, {"id": "fauna", "min_zoom": 7, "label_de": "Tiere", "label_en": "Animals", "question_de": "Welche winzigen Tiere leben hier?", "question_en": "Which tiny animals live here?", "answer_de": "Zu den häufigen Gruppen gehören Fadenwürmer, Bärtierchen, Rädertierchen, Springschwänze und Milben.", "answer_en": "Common groups include nematodes, tardigrades, rotifers, springtails and mites.", "source_citations": [{"label": "Australian Antarctic Program · Land invertebrates", "url": "https://www.antarctica.gov.au/about-antarctica/animals/land-invertebrates/"}], "station_slug": "antarctic-life-extrem-fauna"}, {"id": "soil", "min_zoom": 12, "label_de": "Lebensraum", "label_en": "Habitat", "question_de": "Wie überstehen sie Frost?", "question_en": "How do they survive frost?", "answer_de": "Viele antarktische Wirbellose überleben Minusgrade, ohne zu gefrieren. Temperaturänderungen verändern auch die Verfügbarkeit von Wasser.", "answer_en": "Many Antarctic invertebrates survive subzero temperatures without freezing. Temperature changes also affect water availability.", "source_citations": [{"label": "Australian Antarctic Program · Land invertebrates", "url": "https://www.antarctica.gov.au/about-antarctica/animals/land-invertebrates/"}], "station_slug": "antarctic-life-extrem-soil"}], "summary_en": "Representative learning region: Which tiny animals live here?"}'::jsonb) on conflict (slug) do nothing;
insert into public.ecosystem_hotspots (slug,region_slug,priority,category,title_de,teaser_de,detail_de,latitude,longitude,status,source_citations,related_paths,explorer_data) values ('antarctic-life-extrem-fauna','antarctic-life-extrem',1,'species','Welche winzigen Tiere leben hier?','Zu den häufigen Gruppen gehören Fadenwürmer, Bärtierchen, Rädertierchen, Springschwänze und Milben.','Beispielhafte Lernregion. Der räumliche Geltungsbereich ist in der Quelle beschrieben.',-64.5,-62,'published','[{"label": "Australian Antarctic Program · Land invertebrates", "url": "https://www.antarctica.gov.au/about-antarctica/animals/land-invertebrates/"}]'::jsonb,'[]'::jsonb,'{"title_en": "Which tiny animals live here?", "teaser_en": "Common groups include nematodes, tardigrades, rotifers, springtails and mites.", "detail_en": "Representative learning region; see source for geographic scope.", "location_scope": "representative_region", "reviewed_on": "2026-11-28"}'::jsonb) on conflict (slug) do nothing;
insert into public.ecosystem_hotspots (slug,region_slug,priority,category,title_de,teaser_de,detail_de,latitude,longitude,status,source_citations,related_paths,explorer_data) values ('antarctic-life-extrem-soil','antarctic-life-extrem',2,'soil','Wie überstehen sie Frost?','Viele antarktische Wirbellose überleben Minusgrade, ohne zu gefrieren. Temperaturänderungen verändern auch die Verfügbarkeit von Wasser.','Beispielhafte Lernregion. Der räumliche Geltungsbereich ist in der Quelle beschrieben.',-64.5,-62,'published','[{"label": "Australian Antarctic Program · Land invertebrates", "url": "https://www.antarctica.gov.au/about-antarctica/animals/land-invertebrates/"}]'::jsonb,'[]'::jsonb,'{"title_en": "How do they survive frost?", "teaser_en": "Many Antarctic invertebrates survive subzero temperatures without freezing. Temperature changes also affect water availability.", "detail_en": "Representative learning region; see source for geographic scope.", "location_scope": "representative_region", "reviewed_on": "2026-11-28"}'::jsonb) on conflict (slug) do nothing;
